"""Built-in zero-build administration and RAG workbench UI.

The page contains no embedded credentials. Operators enter an API key which is
kept in browser sessionStorage and sent only to Ragbot API endpoints. The UI is
served directly by FastAPI and deliberately has no npm/build dependency.
"""
from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse


def create_admin_ui_router() -> APIRouter:
    router = APIRouter(tags=["admin-ui"])

    @router.get("/admin/ui", response_class=HTMLResponse, include_in_schema=False)
    async def admin_ui() -> str:
        return _HTML

    return router


_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ragbot Control Plane · RAG Workbench</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:#182033;background:#f4f6fa;--ink:#111827;--muted:#667085;--line:#e5e7eb;--brand:#111827;--good:#067647;--bad:#b42318;--warn:#b54708}
*{box-sizing:border-box}body{margin:0}.top{position:sticky;top:0;z-index:20;background:#101828;color:white;padding:13px 24px;display:flex;align-items:center;gap:12px;box-shadow:0 1px 5px #0002}.brand{font-size:18px;font-weight:750;margin-right:auto}.brand small{font-size:11px;font-weight:500;color:#98a2b3;margin-left:9px}.top input{width:210px;background:#1d2939;border:1px solid #475467;color:white;border-radius:8px;padding:8px 10px}.top button{background:white;color:#111827}.pill{display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:999px;background:#eef2ff;font-size:11px;white-space:nowrap}.top .pill{background:#344054;color:white}.shell{max-width:1680px;margin:auto;padding:18px 24px 40px}.tabs{display:flex;gap:5px;margin:0 0 16px;background:#e9edf4;width:max-content;border-radius:9px;padding:4px}.tab{background:transparent;color:#475467;padding:7px 13px}.tab.active{background:white;color:#101828;box-shadow:0 1px 2px #0002}.view{display:none}.view.active{display:block}.cards{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));gap:10px}.card,.panel{background:white;border:1px solid var(--line);border-radius:11px;box-shadow:0 1px 2px #1018280a}.card{padding:13px 15px}.card .k{color:var(--muted);font-size:11px}.card b{display:block;font-size:24px;margin-top:5px}.layout{display:grid;grid-template-columns:minmax(320px,410px) minmax(0,1fr);gap:14px;margin-top:14px}.layout.equal{grid-template-columns:1fr 1fr}.panel{padding:16px;overflow:auto}.panel h2{font-size:15px;margin:0}.panel h3{font-size:13px;margin:18px 0 8px}.head{display:flex;align-items:center;gap:8px;margin-bottom:12px}.head .muted{margin-left:auto}.muted{color:var(--muted);font-size:12px}.hint{padding:9px 10px;border-radius:8px;background:#f2f4f7;color:#475467;font-size:12px;margin:8px 0}.warning{background:#fff6ed;color:#9a3412;border:1px solid #fed7aa}.success{background:#ecfdf3;color:#067647;border:1px solid #abefc6}.error{background:#fef3f2;color:#b42318;border:1px solid #fecdca}.message{position:fixed;right:22px;bottom:20px;z-index:50;max-width:520px;padding:11px 13px;border-radius:9px;background:#101828;color:white;box-shadow:0 8px 24px #0003;font-size:12px;white-space:pre-wrap}.hidden{display:none!important}label{display:block;font-size:11px;font-weight:650;color:#475467;margin:10px 0 4px}input,select,textarea,button{font:inherit}input,select,textarea{width:100%;border:1px solid #d0d5dd;border-radius:8px;padding:8px 9px;background:white;color:#101828}textarea{min-height:84px;resize:vertical}button{border:0;border-radius:8px;padding:8px 11px;cursor:pointer;background:#101828;color:white;font-weight:600}button.secondary{background:#eaecf0;color:#344054}button.danger{background:#b42318}button.ghost{background:transparent;color:#344054;border:1px solid #d0d5dd}button:disabled{opacity:.45;cursor:not-allowed}.actions{display:flex;gap:6px;flex-wrap:wrap}.actions button{padding:5px 8px;font-size:11px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px}.metricline{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:10px 0}.metric{background:#f8fafc;border:1px solid #eaecf0;border-radius:8px;padding:9px}.metric b{display:block;font-size:18px}.progress{height:9px;background:#eaecf0;border-radius:99px;overflow:hidden;margin:8px 0}.progress>div{height:100%;background:#12b76a;transition:width .3s}.progress.failed>div{background:#f04438}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid #eef0f4;font-size:12px;vertical-align:top}th{font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:#667085;background:#fcfcfd;position:sticky;top:0}.mono,code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}.truncate{max-width:420px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.status-ok{background:#ecfdf3;color:#067647}.status-bad{background:#fef3f2;color:#b42318}.status-warn{background:#fffaeb;color:#b54708}.searchbar{display:grid;grid-template-columns:minmax(240px,1fr) 90px 130px auto;gap:8px;align-items:end}.searchbar textarea{min-height:66px}.result{border:1px solid #e4e7ec;border-radius:10px;margin:9px 0;padding:12px;background:#fff}.resultTop{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:7px}.resultRank{font-weight:800;font-size:15px}.score{font-family:ui-monospace,monospace;font-size:11px;background:#f2f4f7;border-radius:6px;padding:3px 6px}.resultText{font-size:13px;line-height:1.55;white-space:pre-wrap}.trace{display:flex;gap:7px;flex-wrap:wrap;margin-top:8px}.runtime{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}.runtime .pill{background:#f2f4f7;color:#344054}.samples{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.samples button{font-size:11px;background:#f2f4f7;color:#344054}.empty{padding:28px;text-align:center;color:#98a2b3}.permission{font-size:12px;padding:8px 10px;background:#f2f4f7;border-radius:8px}.split{display:grid;grid-template-columns:1.15fr .85fr;gap:14px}.jobbox{border:1px solid #e4e7ec;border-radius:10px;padding:12px;margin-top:12px}.fileTitle{font-weight:700;word-break:break-all}.queuegrid{display:grid;grid-template-columns:1fr 1fr;gap:7px;font-size:12px}.footer{margin-top:18px;color:#98a2b3;font-size:11px;text-align:right}
@media(max-width:1200px){.cards{grid-template-columns:repeat(4,1fr)}.layout,.layout.equal,.split{grid-template-columns:1fr}.searchbar{grid-template-columns:1fr 90px}.searchbar button{width:max-content}}
@media(max-width:700px){.shell{padding:12px}.top{padding:10px 12px}.top input{width:140px}.cards{grid-template-columns:repeat(2,1fr)}.metricline,.row,.row3{grid-template-columns:1fr}.searchbar{grid-template-columns:1fr}.brand small{display:none}}
</style>
</head>
<body>
<header class="top"><div class="brand">Ragbot Control Plane <small>RAG Workbench</small></div><span id="roleBadge" class="pill">Disconnected</span><input id="tenant" placeholder="tenant" value="engineering"><input id="key" type="password" placeholder="X-API-Key (session only)"><button onclick="saveAndRefresh()">Connect / Refresh</button></header>
<main class="shell">
<div class="tabs"><button class="tab active" data-tab="overview" onclick="showTab('overview')">Overview</button><button class="tab" data-tab="ingestion" onclick="showTab('ingestion')">PDF Ingestion</button><button class="tab" data-tab="retrieval" onclick="showTab('retrieval')">Retrieval Playground</button></div>

<section id="view-overview" class="view active">
<div class="cards">
 <div class="card"><span class="k">Sources</span><b id="mSources">-</b></div><div class="card"><span class="k">Documents</span><b id="mDocs">-</b></div><div class="card"><span class="k">Chunks</span><b id="mChunks">-</b></div><div class="card"><span class="k">Pending</span><b id="mPending">-</b></div><div class="card"><span class="k">Running</span><b id="mRunning">-</b></div><div class="card"><span class="k">Failed</span><b id="mFailed">-</b></div><div class="card"><span class="k">Dead Lettered</span><b id="mDeadLettered">-</b></div><div class="card"><span class="k">Scheduled</span><b id="mScheduled">-</b></div>
</div>
<div class="layout">
 <div class="panel"><div class="head"><h2>Queue health</h2><span id="permissionHint" class="muted">Connect to load permissions.</span></div><div id="queueHealth" class="queuegrid"><span class="muted">Connect to load metrics.</span></div><h3>Operator guidance</h3><div class="hint">Use <b>PDF Ingestion</b> for one local PDF and immediate indexing feedback. Use <b>Retrieval Playground</b> to inspect vector, lexical and RRF ranking instead of judging only the final score.</div></div>
 <div class="panel"><div class="head"><h2>Source Catalog</h2><span id="sourceCount" class="muted"></span></div><table><thead><tr><th>Source</th><th>Status</th><th>Last index</th><th>Schedule</th><th>Actions</th></tr></thead><tbody id="sourceRows"></tbody></table></div>
</div>
<div class="panel" style="margin-top:14px"><div class="head"><h2>Recent Ingestion Jobs</h2><span class="muted">docs / total chunks · written / reused</span></div><table><thead><tr><th>Job</th><th>Source</th><th>Status / Failure</th><th>Knowledge</th><th>Timing</th><th>Actions</th></tr></thead><tbody id="jobRows"></tbody></table></div>
</section>

<section id="view-ingestion" class="view">
<div class="split">
 <div class="panel"><div class="head"><h2>Single PDF ingestion</h2><span class="pill">PDF → chunks → embedding → index</span></div><div class="hint">The path is resolved by the Ragbot server, so for local mode use a file below the repository <code>data</code> directory. Quoted spaces are not needed in this browser form.</div><label>Tenant</label><input id="pdfTenant" value="engineering"><label>PDF path</label><input id="pdfPath" placeholder="D:\Project\ragbot\data\book.pdf"><div class="row3"><div><label>Chunk size</label><input id="pdfChunk" type="number" value="800" min="100"></div><div><label>Overlap</label><input id="pdfOverlap" type="number" value="100" min="0"></div><div><label>Tag</label><input id="pdfTag" value="pdf"></div></div><label>Source name (optional)</label><input id="pdfName" placeholder="DeepSeek in Action"><div class="actions" style="margin-top:13px"><button id="pdfIngestButton" onclick="ingestPdf()">Ingest PDF</button><button class="secondary" onclick="openSearchForPdf()">Test retrieval</button></div><div id="pdfPermission" class="permission" style="margin-top:12px">Connect to determine operator or owner capability.</div></div>
 <div class="panel"><div class="head"><h2>Current ingestion</h2><span class="muted">job lifecycle</span></div><div id="pdfJobEmpty" class="empty">Submit a PDF to watch the job here.</div><div id="pdfJob" class="jobbox hidden"><div class="fileTitle" id="pdfJobTitle"></div><div class="runtime"><span id="pdfJobStatus" class="pill"></span><span id="pdfJobId" class="pill mono"></span></div><div id="pdfProgress" class="progress"><div style="width:0%"></div></div><div id="pdfProgressLabel" class="muted"></div><div class="metricline"><div class="metric"><span class="muted">Documents</span><b id="pdfDocs">0</b></div><div class="metric"><span class="muted">Chunks total</span><b id="pdfChunks">0</b></div><div class="metric"><span class="muted">Written</span><b id="pdfWritten">0</b></div><div class="metric"><span class="muted">Reused</span><b id="pdfReused">0</b></div></div><div id="pdfJobDetails" class="hint"></div></div></div>
</div>
<div class="panel" style="margin-top:14px"><details><summary><b>Generic Quick Import</b> <span class="muted">local_fs, web, repo, S3, Drive, Notion, Confluence</span></summary><div class="layout equal"><div><label>Location</label><input id="qLocation" placeholder="/data/manuals, https://..., s3://..."><label>Name</label><input id="qName"><label>Tags (comma separated)</label><input id="qTags"><label>Credential reference (cloud/SaaS only)</label><input id="qCredentialRef" placeholder="env:RAGBOT_NOTION_TOKEN"><div class="hint">Only an environment-variable reference is accepted. Never paste a token, password or private key here.</div></div><div><label>Connector config JSON (non-secret)</label><textarea id="qConfig" placeholder='{"recursive":true}'></textarea><label>Idempotency key</label><input id="qIdempotency"><button style="margin-top:12px" id="quickImportButton" onclick="quickImport()">Create / Ingest</button></div></div></details></div>
</section>

<section id="view-retrieval" class="view">
<div class="panel"><div class="head"><h2>Retrieval Playground</h2><span class="muted">inspect retrieval before testing answer synthesis</span></div><div class="searchbar"><div><label>Query</label><textarea id="searchQuery" placeholder="What is the difference between LoRA and QLoRA?"></textarea></div><div><label>Top K</label><input id="searchTopK" type="number" value="10" min="1" max="100"></div><div><label>Source type</label><select id="searchSourceType"><option value="">all</option><option value="pdf" selected>pdf</option><option value="local_fs">local_fs</option><option value="web">web</option><option value="repo">repo</option></select></div><button onclick="runSearch()">Search</button></div><div class="samples"><button onclick="sampleQuery('What is the difference between LoRA and QLoRA?')">LoRA vs QLoRA</button><button onclick="sampleQuery('How can quantization reduce GPU memory usage during LLM deployment?')">Quantization / GPU memory</button><button onclick="sampleQuery('大模型部署时如何减少显存占用？')">中文跨语言检索</button></div><div id="runtimeDiag" class="runtime"></div><div id="searchWarning"></div><div id="searchSummary" class="muted" style="margin:8px 0"></div><div id="searchResults"><div class="empty">Run a query to inspect vector, lexical and fused rankings.</div></div></div>
</section>
<div class="footer">Ragbot zero-build admin UI · API key is kept only in browser sessionStorage</div>
</main>
<div id="msg" class="message hidden"></div>
<script>
const $=id=>document.getElementById(id);let sourceById={},capabilities={read:false,operate:false,admin:false},activePdfJob=null,refreshTimer=null;
function headers(){const h={'Content-Type':'application/json'},k=$('key').value.trim();if(k)h['X-API-Key']=k;return h}
function tenant(){return $('tenant').value.trim()||'default'}
function tenantQuery(){return '?tenant_id='+encodeURIComponent(tenant())}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function msg(text,bad=false){const e=$('msg');e.textContent=text;e.classList.remove('hidden');e.style.background=bad?'#7a271a':'#101828';setTimeout(()=>e.classList.add('hidden'),6500)}
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{...headers(),...(opts.headers||{})}});if(!r.ok){let d;try{d=await r.json()}catch{d={detail:await r.text()}}throw new Error(`${r.status}: ${d.detail||JSON.stringify(d)}`)}return r.status===204?null:r.json()}
function showTab(name){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('view-'+name).classList.add('active')}
function saveAndRefresh(){sessionStorage.setItem('ragbotKey',$('key').value);sessionStorage.setItem('ragbotTenant',$('tenant').value);$('pdfTenant').value=tenant();refresh();if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(refresh,5000)}
async function refresh(){try{const q=tenantQuery(),[session,o,s,j]=await Promise.all([api('/catalog/session'),api('/catalog/overview'+q),api('/catalog/sources'+q),api('/catalog/jobs'+q)]);renderSession(session);renderOverview(o);renderSources(s.sources);renderJobs(j.jobs)}catch(e){msg(e.message,true)}}
function renderSession(s){capabilities=s.capabilities||{read:true,operate:false,admin:false};const roles=s.admin?['admin']:(s.roles||[]);$('roleBadge').textContent=roles.length?roles.join(' / '):(s.principal_mode==='development'?'development owner':'reader');const can=!!capabilities.operate;$('quickImportButton').disabled=!can;$('pdfIngestButton').disabled=!can;const t=can?'Operator capability enabled.':'Read-only principal: ingestion, retry/requeue and schedule mutations require operator or owner.';$('permissionHint').textContent=t;$('pdfPermission').textContent=t}
function renderOverview(o){$('mSources').textContent=o.sources.total;$('mDocs').textContent=o.knowledge.documents;$('mChunks').textContent=o.knowledge.chunks;$('mPending').textContent=o.queue.pending;$('mRunning').textContent=o.queue.running;$('mFailed').textContent=o.queue.failed;$('mDeadLettered').textContent=o.queue.dead_lettered??0;$('mScheduled').textContent=o.sources.scheduled;$('queueHealth').innerHTML=`<div>Oldest pending<br><b>${Math.round(o.queue.oldest_pending_age_seconds)}s</b></div><div>Stale leases<br><b>${o.queue.stale_running_leases}</b></div><div>Completed 24h<br><b>${o.queue.completed_24h}</b></div><div>Failed 24h<br><b>${o.queue.failed_24h}</b></div><div>Dead-lettered 24h<br><b>${o.queue.dead_lettered_24h??0}</b></div><div>Next sync<br><b>${esc(o.sources.next_sync_at||'none')}</b></div>`}
function statusPill(s){const c=s==='completed'||s==='active'?'status-ok':s==='failed'||s==='dead_lettered'?'status-bad':s==='running'||s==='pending'?'status-warn':'';return `<span class="pill ${c}">${esc(s)}</span>`}
function renderSources(items){sourceById={};$('sourceCount').textContent=`${items.length} shown`;$('sourceRows').innerHTML=items.map(s=>{sourceById[s.source_id]=s;const j=s.latest_job||{},li=s.last_index||{},sy=s.sync||{},actions=capabilities.operate?`<div class="actions"><button onclick="ingestNow('${s.source_id}','${esc(s.tenant_id)}')">Ingest</button><button class="secondary" onclick="toggleSource('${s.source_id}','${s.status}')">${s.status==='paused'?'Resume':'Pause'}</button><button class="secondary" onclick="configureSync('${s.source_id}')">Sync</button></div>`:'<span class="muted">read-only</span>';return `<tr><td><b>${esc(s.name)}</b><div class="muted">${esc(s.tenant_id)} · ${esc(s.source_type)}</div><div class="muted truncate" title="${esc(s.location||'')}">${esc(s.location||'')}</div></td><td>${statusPill(s.status)}<div class="muted">job ${esc(j.status||'never')}</div></td><td><b>${li.documents||0} docs / ${li.chunks||0} chunks</b><div class="muted">${esc(li.completed_at||'')}</div></td><td>${sy.enabled?`every ${Math.round((sy.interval_seconds||0)/60)} min<br><span class="muted">${esc(sy.next_at||'')}</span>`:'off'}</td><td>${actions}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No sources for this tenant</td></tr>'}
function duration(j){if(!j.started_at||!j.completed_at)return '—';const ms=new Date(j.completed_at)-new Date(j.started_at);return ms>=0?(ms/1000).toFixed(1)+'s':'—'}
function renderJobs(items){$('jobRows').innerHTML=items.map(j=>{let actions='<span class="muted">—</span>';if(capabilities.operate&&j.status==='failed')actions=`<button onclick="retryJob('${j.job_id}')">Retry</button>`;if(capabilities.operate&&j.status==='dead_lettered')actions=`<button class="danger" onclick="requeueJob('${j.job_id}')">Requeue snapshot</button>`;const st=j.stats||{},total=st.chunks_total??j.chunk_count??0,written=st.chunks_ingested??j.chunk_count??0,reused=st.chunks_reused??0;return `<tr><td><code>${esc(j.job_id.slice(0,12))}</code><div class="muted">attempts ${j.attempts||0}</div></td><td><code>${esc(j.source_id.slice(0,12))}</code><div class="muted">${esc(j.tenant_id)} · ${esc(j.source_type||'')}</div></td><td>${statusPill(j.status)}${j.failure_class?`<div class="muted">class: ${esc(j.failure_class)}</div>`:''}${j.error?`<div class="muted" title="${esc(j.error)}">${esc(j.error.slice(0,180))}</div>`:''}</td><td><b>${j.doc_count||0} / ${total}</b><div class="muted">written ${written} · reused ${reused}</div></td><td><div class="muted">${duration(j)}<br>created ${esc(j.created_at||'')}<br>done ${esc(j.completed_at||'')}</div></td><td><div class="actions">${actions}</div></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No jobs</td></tr>'}
function requireOperate(){if(!capabilities.operate)throw new Error('This API principal is read-only; operator or owner role required')}
async function quickImport(){try{requireOperate();const location=$('qLocation').value.trim();if(!location)throw new Error('location is required');const body={tenant_id:tenant(),location};if($('qName').value.trim())body.name=$('qName').value.trim();const tags=$('qTags').value.split(',').map(x=>x.trim()).filter(Boolean);if(tags.length)body.tags=tags;let config={};const raw=$('qConfig').value.trim();if(raw){config=JSON.parse(raw);if(!config||Array.isArray(config)||typeof config!=='object')throw new Error('connector config must be a JSON object')}const credentialRef=$('qCredentialRef').value.trim();if(credentialRef)config.credential_ref=credentialRef;if(Object.keys(config).length)body.config=config;if($('qIdempotency').value.trim())body.idempotency_key=$('qIdempotency').value.trim();const r=await api('/ingest/quick',{method:'POST',body:JSON.stringify(body)});msg(`Queued ${r.job_id}`);refresh()}catch(e){msg(e.message,true)}}
async function ingestPdf(){try{requireOperate();const path=$('pdfPath').value.trim();if(!path)throw new Error('PDF path is required');if(!path.toLowerCase().endsWith('.pdf'))throw new Error('The selected path must end in .pdf');const config={chunk_size:Number($('pdfChunk').value||800),chunk_overlap:Number($('pdfOverlap').value||100)};const body={tenant_id:$('pdfTenant').value.trim()||tenant(),location:path,source_type:'pdf',config,tags:[$('pdfTag').value.trim()||'pdf']};if($('pdfName').value.trim())body.name=$('pdfName').value.trim();const r=await api('/ingest/quick',{method:'POST',body:JSON.stringify(body)});activePdfJob=r.job_id;$('pdfJobTitle').textContent=$('pdfName').value.trim()||path;$('pdfJobId').textContent=r.job_id.slice(0,12);$('pdfJobEmpty').classList.add('hidden');$('pdfJob').classList.remove('hidden');msg(`PDF ingestion queued: ${r.job_id}`);pollPdfJob(r.job_id)}catch(e){msg(e.message,true)}}
async function pollPdfJob(id){if(activePdfJob!==id)return;try{const j=await api('/ingest/jobs/'+encodeURIComponent(id));renderPdfJob(j);if(j.status==='pending'||j.status==='running')setTimeout(()=>pollPdfJob(id),800);else refresh()}catch(e){msg(e.message,true)}}
function renderPdfJob(j){const st=j.stats||{},total=st.chunks_total??j.chunk_count??0,written=st.chunks_ingested??j.chunk_count??0,reused=st.chunks_reused??0;let pct=j.status==='pending'?12:j.status==='running'?62:j.status==='completed'?100:j.status==='failed'||j.status==='dead_lettered'?100:5;$('pdfJobStatus').outerHTML=statusPill(j.status).replace('<span','<span id="pdfJobStatus"');const p=$('pdfProgress');p.classList.toggle('failed',j.status==='failed'||j.status==='dead_lettered');p.firstElementChild.style.width=pct+'%';$('pdfProgressLabel').textContent=j.status==='running'?'Processing document and vector index…':j.status==='completed'?'Knowledge index ready.':j.status==='pending'?'Waiting for worker…':(j.error||j.status);$('pdfDocs').textContent=j.doc_count||0;$('pdfChunks').textContent=total;$('pdfWritten').textContent=written;$('pdfReused').textContent=reused;$('pdfJobDetails').innerHTML=`Duration: <b>${duration(j)}</b> · removed chunks: <b>${st.chunks_removed??0}</b>${j.error?`<br><span style="color:#b42318">${esc(j.error)}</span>`:''}`}
function openSearchForPdf(){showTab('retrieval');if(!$('searchQuery').value.trim())$('searchQuery').value='Summarize the most important technical concepts in this document.'}
function sampleQuery(q){$('searchQuery').value=q;runSearch()}
async function runSearch(){try{const query=$('searchQuery').value.trim();if(!query)throw new Error('query is required');const filters={},sourceType=$('searchSourceType').value;if(sourceType)filters.source_types=[sourceType];const body={query,tenant_id:tenant(),user_id:'admin-ui',top_k:Number($('searchTopK').value||10),filters:Object.keys(filters).length?filters:null};const started=performance.now();const r=await api('/search',{method:'POST',body:JSON.stringify(body)});const elapsed=Math.round(performance.now()-started);renderSearch(r,elapsed)}catch(e){msg(e.message,true)}}
function renderSearch(r,elapsed){const d=r.diagnostics||{};$('runtimeDiag').innerHTML=[`Embedding: ${d.embedding_model||'unknown'}`,`${d.embedding_dimension||'?'}D`,d.semantic_embedding?'semantic':'development fallback',`Vector: ${d.vector_store||'?'}`,`Repo: ${d.repository||'?'}`,d.reranker_enabled?`Reranker: ${d.reranker}`:'Reranker: off'].map(x=>`<span class="pill">${esc(x)}</span>`).join('');const warnings=d.warnings||[];$('searchWarning').innerHTML=warnings.map(w=>`<div class="hint warning">${esc(w)}</div>`).join('');const chunks=r.chunks||[];const lexicalHits=chunks.filter(c=>c.metadata?._retrieval?.lexical).length,vectorHits=chunks.filter(c=>c.metadata?._retrieval?.vector).length;$('searchSummary').textContent=`${chunks.length} results · ${elapsed} ms · vector-supported ${vectorHits} · lexical-supported ${lexicalHits} · request ${String(r.request_id||'').slice(0,12)}`;$('searchResults').innerHTML=chunks.map((c,i)=>{const m=c.metadata||{},t=m._retrieval||{},v=t.vector,l=t.lexical,page=m.page??'—',section=m.section||'—';return `<article class="result"><div class="resultTop"><span class="resultRank">#${i+1}</span><span class="score">final ${fmt(c.score)}</span><span class="pill">page ${esc(page)}</span><span class="pill">${esc(section)}</span><span class="muted mono">${esc(c.chunk_id.slice(0,16))}</span></div><div class="resultText">${esc(c.text)}</div><div class="trace"><span class="score">vector ${v?`#${v.rank} · ${fmt(v.score)}`:'—'}</span><span class="score">lexical ${l?`#${l.rank} · ${fmt(l.score)}`:'—'}</span><span class="score">RRF ${fmt(t.rrf_score)}</span>${t.rerank_score!=null?`<span class="score">rerank ${fmt(t.rerank_score)}</span>`:''}<span class="score">model ${esc(t.embedding_model||m.embedding_model||'?')}</span></div></article>`}).join('')||'<div class="empty">No retrieval results.</div>'}
function fmt(v){return v==null?'—':Number(v).toFixed(5)}
async function ingestNow(id,t){try{requireOperate();const r=await api('/ingest/jobs',{method:'POST',body:JSON.stringify({source_id:id,tenant_id:t})});msg(`Queued ${r.job_id}`);refresh()}catch(e){msg(e.message,true)}}
async function retryJob(id){try{requireOperate();const r=await api(`/ingest/jobs/${id}/retry`,{method:'POST'});msg(`Retry queued ${r.job_id}`);refresh()}catch(e){msg(e.message,true)}}
async function requeueJob(id){try{requireOperate();const r=await api(`/ingest/jobs/${id}/requeue`,{method:'POST',body:JSON.stringify({use_current_source_config:false})});msg(`Requeue snapshot queued ${r.job_id}`);refresh()}catch(e){msg(e.message,true)}}
async function toggleSource(id,status){try{requireOperate();await api(`/sources/${id}`,{method:'PUT',body:JSON.stringify({status:status==='paused'?'active':'paused'})});refresh()}catch(e){msg(e.message,true)}}
async function configureSync(id){try{requireOperate();const s=sourceById[id],current=s?.sync?.interval_seconds||3600;const raw=prompt('Sync interval in seconds. Enter 0 to disable.',String(current));if(raw===null)return;const seconds=Number(raw);if(!Number.isFinite(seconds)||seconds<0)throw new Error('invalid interval');await api(`/sources/${id}/sync`,{method:'PUT',body:JSON.stringify(seconds===0?{enabled:false}:{enabled:true,interval_seconds:seconds,run_immediately:false})});refresh()}catch(e){msg(e.message,true)}}
$('key').value=sessionStorage.getItem('ragbotKey')||'';$('tenant').value=sessionStorage.getItem('ragbotTenant')||'engineering';$('pdfTenant').value=$('tenant').value;refresh();refreshTimer=setInterval(refresh,5000);
</script>
</body></html>'''
